/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'C Capping';
  const equipment = {};

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', { length: 2.4 }, ctx);
  root.add(equipment.belt.root);

  // capper: A machine put together from parts (basic frames, axes, tools), each on a...
  equipment.capper = registry.buildComponent('composite', {
    parts: [
      { id: 'arm', type: 'cantileverFrame', params: { reach: 0.8, height: 1.9 } },
      {
        id: 'lift',
        type: 'verticalAxis',
        params: { stroke: 0.25, bodyLength: 0.35 },
        on: 'arm.tip',
      },
      {
        id: 'wrist',
        type: 'rotaryAxis',
        params: { hang: true, radius: 0.05, height: 0.08 },
        on: 'lift.ram',
      },
      {
        id: 'chuck',
        type: 'fingerGripper',
        params: { fingerLength: 0.08, maxGap: 0.08 },
        on: 'wrist.flange',
      },
    ],
    motions: { lower: 'lift.extend', spin: 'wrist.angle', grip: 'chuck.grip' },
    anchors: { tool: 'chuck' },
  }, ctx);
  root.add(equipment.capper.root);

  return { root, equipment };
}
